// A painted still with water-only scanline displacement: the buildings remain perfectly still.
export class Illustration {
 constructor(city,canvas,water){this.city=city;this.canvas=canvas;this.ctx=canvas.getContext('2d');this.water=water;this.image=null;this.previous=null;this.token=0;this.transitionStart=0;this.cache=new Map();this.visible=true;this.failed=false;new ResizeObserver(()=>{this.resize();this.render(performance.now()/1000,this.animated??false);}).observe(canvas.parentElement);this.resize();}
 resize(){const r=this.canvas.parentElement.getBoundingClientRect();this.w=r.width;this.h=r.height;this.dpr=Math.min(devicePixelRatio,1.5);this.canvas.width=Math.round(this.w*this.dpr);this.canvas.height=Math.round(this.h*this.dpr);}
 async load(url,animate=true){if(url===this.url)return;this.url=url;const token=++this.token;let image=this.cache.get(url);try{if(!image){image=new Image();image.src=url;await image.decode();this.cache.set(url,image);if(this.cache.size>10)this.cache.delete(this.cache.keys().next().value);}if(token!==this.token)return;this.previous=animate?this.image:null;this.image=image;this.failed=false;this.transitionStart=performance.now()/1000;this.render(this.transitionStart,animate);}catch(error){if(token!==this.token)return;this.failed=true;this.canvas.dispatchEvent(new CustomEvent('art-error',{detail:{url}}));console.warn('Illustration unavailable',url);}}
 draw(image,t,animated,alpha=1){const {ctx,w,h,dpr}=this,iw=image.naturalWidth,ih=image.naturalHeight,scale=Math.max(w/iw,h/ih),dw=iw*scale,dh=ih*scale,focus=this.water.focus??.5,dx=(w-dw)*focus,dy=(h-dh)/2;ctx.save();ctx.globalAlpha=alpha;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.drawImage(image,dx,dy,dw,dh);if(animated){ctx.beginPath();const waterY=ih*this.water.start;ctx.moveTo(dx+iw*this.water.left*scale,dy+waterY*scale);ctx.lineTo(dx+dw,dy+waterY*scale);ctx.lineTo(dx+dw,dy+dh);ctx.lineTo(dx+iw*(this.water.foreground?.39:0)*scale,dy+dh);if(this.water.foreground)ctx.lineTo(dx+iw*.24*scale,dy+ih*.88*scale);ctx.closePath();ctx.clip();const flow=this.water.motion,phase=flow.phase,slowTime=t*flow.rate,step=2;for(let sy=Math.floor(waterY);sy<ih-step;sy+=step){const depth=(sy-waterY)/(ih-waterY),edge=Math.min(1,depth*5);const shift=edge*flow.amplitude*(Math.sin(sy*flow.band+slowTime*flow.direction+phase)+.45*Math.sin(sy*flow.secondary-slowTime*.61+phase*2.37))*(.45+depth*.55);const sampleY=Math.min(ih-step-1,Math.max(waterY,sy+Math.sin(sy*flow.band-slowTime*.43+phase)*.2*edge));ctx.drawImage(image,0,sampleY,iw,step,dx+shift*scale,dy+sy*scale,dw,step*scale+.5);}
 // Sparse glints travel with the current; they are clipped to the river, not the skyline.
 ctx.globalAlpha=alpha*.09;ctx.strokeStyle=this.url?.includes('night')||this.url?.includes('evening')?'#f0bf73':'#fff7db';ctx.lineWidth=.8;for(let i=0;i<15;i++){const depth=.12+((i*.137+phase*.11)%.83),travel=i*173+phase*97+t*flow.drift*flow.direction*(.6+depth*.9),x=((travel%(iw+100))+(iw+100))%(iw+100)-50,y=waterY+(ih-waterY)*depth+Math.sin(slowTime*.45+i+phase)*.3;ctx.beginPath();ctx.moveTo(dx+x*scale,dy+y*scale);ctx.lineTo(dx+(x+12+depth*25)*scale,dy+(y+.8)*scale);ctx.stroke();}}
 ctx.restore();}
 render(t,animated){this.animated=animated;if(!this.visible||!this.image||!this.ctx)return;const progress=this.previous&&animated?Math.max(0,Math.min(1,(t-this.transitionStart)/2.6)):1,blend=progress*progress*(3-2*progress);this.ctx.clearRect(0,0,this.canvas.width,this.canvas.height);if(this.previous&&blend<1)this.draw(this.previous,t,animated,1);this.draw(this.image,t,animated,blend);if(blend>=1)this.previous=null;}
}



